package com.wizzadrds.theworldremembers.equipment; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; public record NpcEquipment(String mainHand,String head,String chest,String legs,String feet){public static final Codec<NpcEquipment> CODEC=RecordCodecBuilder.create(i->i.group(Codec.STRING.optionalFieldOf("mainHand","minecraft:air").forGetter(NpcEquipment::mainHand),Codec.STRING.optionalFieldOf("head","minecraft:air").forGetter(NpcEquipment::head),Codec.STRING.optionalFieldOf("chest","minecraft:air").forGetter(NpcEquipment::chest),Codec.STRING.optionalFieldOf("legs","minecraft:air").forGetter(NpcEquipment::legs),Codec.STRING.optionalFieldOf("feet","minecraft:air").forGetter(NpcEquipment::feet)).apply(i,NpcEquipment::new));}
